macro.command:
const pass = args[0].macroPass;
const affected = workflow.actor;
const combat = game.combat;
// 清理上一版宏留下的常驻监听。
if (globalThis.slow2014Casts instanceof WeakMap) {
  Hooks.off("dnd5e.postActivityConsumption", globalThis.slow2014Casts.hook);
  delete globalThis.slow2014Casts;
}
const casts = globalThis.slow2014Casts ??= new Map();

function clearCast(cast) {
  casts.delete(cast);
  if (casts.size) return;
  for (const [event, id] of casts.hooks ?? []) Hooks.off(event, id);
  delete casts.hooks;
}

function watchCast(intercept) {
  casts.set(workflow, {
    intercept,
    effects: new Set(affected.effects.filter(e => e.active
      && (e.system?.origin?.item === macroItem.uuid || e.origin === macroItem.uuid)).map(e => e.uuid))
  });
  if (casts.hooks) return;
  const endEffect = effect => {
    for (const [cast, entry] of casts) {
      if (entry.effects.delete(effect.uuid) && !entry.effects.size) clearCast(cast);
    }
  };
  casts.hooks = [
    // 系统使用同步 Hooks.call；匹配后先解绑，再同步返回拦截结果。
    ["dnd5e.postActivityConsumption", Hooks.on("dnd5e.postActivityConsumption", (activity, usage, message) => {
      const entry = casts.get(usage.workflow);
      if (!entry) return;
      clearCast(usage.workflow);
      return entry.intercept(activity, usage, message);
    })],
    // 取消配置或消耗失败可能不触发 Midi Abort，随迟缓 AE 结束清理遗留记录。
    ["deleteActiveEffect", Hooks.on("deleteActiveEffect", endEffect)],
    ["updateActiveEffect", Hooks.on("updateActiveEffect", effect => {
      if (!effect.active) endEffect(effect);
    })]
  ];
}

async function deferCast(activity, usage, message, roll) {
  if (combat?.started && combat.combatant?.actor?.uuid === affected.uuid) {
    await MidiQOL.setActionUsed(affected);
  }

  // 仅保存可序列化的原生使用配置，保留升环与形态等选择。
  const saved = { ...usage, consume: false };
  for (const key of ["workflow", "activity", "event", "midiOptions"]) delete saved[key];
  if (workflow.deferredConcentration) saved.concentration = { begin: true };

  const ownTurn = combat?.started && combat.combatant?.actor?.uuid === affected.uuid;
  const [effect] = await affected.createEmbeddedDocuments("ActiveEffect", [{
    name: `正在施法：${activity.item.name}`, type: "base", img: activity.item.img,
    system: { origin: { item: activity.item.uuid } },
    duration: combat?.started
      ? { expiry: "targetEnd", ...(ownTurn ? { value: 1, units: "rounds" } : {}) }
      : { value: 12, units: "seconds" },
    flags: { dae: { expiryMode: "delete" } }
  }]);
  const id = foundry.utils.randomID();
  const [temporary] = await affected.createEmbeddedDocuments("Item", [{
    name: `完成施法：${activity.item.name}`, type: "feat", img: activity.item.img, effects: [],
    system: {
      uses: { max: "1", spent: 0, recovery: [] },
      activities: { [id]: {
        _id: id, name: "完成施法", type: "utility",
        activation: { type: "action", value: 1 },
        target: { affects: { type: "self" } },
        consumption: {
          spellSlot: false,
          targets: [{ type: "itemUses", target: "", value: "1" }]
        }
      } }
    },
    flags: {
      dnd5e: { dependentOn: effect.uuid },
      "midi-qol": {
        onUseMacroName: `[preItemRoll]ItemMacro.${macroItem.uuid},[postActiveEffects]ItemMacro.${macroItem.uuid}`
      },
      world: { slowCast: {
        activity: activity.uuid, usage: JSON.parse(JSON.stringify(saved)),
        targets: [...workflow.targets].map(t => t.document.uuid), effect: effect.uuid,
        combat: combat?.id, round: combat?.round, turn: combat?.turn
      } }
    }
  }]);
  await affected.system.addFavorite({
    type: "item", id: foundry.utils.buildRelativeUuid(temporary, affected)
  });
  await roll.toMessage({
    speaker: foundry.documents.ChatMessage.getSpeaker({ actor: affected, token: workflow.token?.document }),
    flavor: `迟缓术：${activity.item.name} 延迟至下一回合。`
  }, { rollMode: message.rollMode ?? game.settings.get("core", "rollMode") });
  await foundry.documents.ChatMessage.implementation.create({
    speaker: foundry.documents.ChatMessage.getSpeaker({ actor: affected, token: workflow.token?.document }),
    content: await foundry.applications.ux.TextEditor.enrichHTML(
      `<p>@UUID[${temporary.uuid}]{${temporary.name}} 已加入收藏。须在下一回合花费一个动作完成，逾期作废。</p>`,
      { relativeTo: affected }
    ),
    whisper: message.data?.whisper ?? [], blind: message.data?.blind ?? false
  });
}

const pending = workflow.item.getFlag("world", "slowCast");

if (pass === "preItemRoll") {
  // 临时物品的完成行动已经支付动作；内部施法不重复检查或掷迟缓骰。
  if (workflow.workflowOptions.slowCompletion || workflow.slowChecked) return;
  workflow.slowChecked = true;

  if (pending && combat?.started && (
    combat.combatant?.actor?.uuid !== affected.uuid
    || (pending.combat === combat.id && pending.round === combat.round && pending.turn === combat.turn)
  )) {
    ui.notifications.warn("须在下一回合完成施法。");
    return false;
  }

  const settings = workflow.workflowOptions;
  const activation = settings.castUsesReaction ? "reaction"
    : settings.castUsesBonusAction ? "bonus" : workflow.activity.effectiveActivationType;
  // 待完成物品可在迟缓结束后保留；以当前 actor OnUse 判断是否仍受迟缓。
  const slowed = affected.getFlag("midi-qol", "onUseMacroParts")?.items.some(m =>
    m.option === "preItemRoll" && m.macroName.split("|")[0] === `ItemMacro.${macroItem.uuid}`);
  if (slowed && combat?.started && combat.combatant?.actor?.uuid === affected.uuid) {
    const used = affected.getFlag("midi-qol", "actions") ?? {};
    if ((activation === "action" && used.bonusActionsUsed > 0) || (activation === "bonus" && used.action)) {
      ui.notifications.warn("迟缓术：本回合只能执行动作或附赠动作。");
      return false;
    }
  }

  if (pending || !slowed || workflow.item.type !== "spell" || activation !== "action"
    || (workflow.activity.activation.value ?? 1) !== 1) return;

  // 先求值但不发消息；原生配置被取消或消耗失败时，不产生待完成记录。
  const roll = await new Roll("1d20").evaluate();
  watchCast((activity, usage, message) => {
    const task = roll.total >= 11 ? deferCast(activity, usage, message, roll)
      : roll.toMessage({
        speaker: foundry.documents.ChatMessage.getSpeaker({ actor: affected, token: workflow.token?.document }),
        flavor: "迟缓术：正常施法。"
      }, { rollMode: message.rollMode ?? game.settings.get("core", "rollMode") });
    task.catch(error => {
      console.error("迟缓术", error);
      ui.notifications.error("迟缓术宏执行失败，详见控制台；已支付的消耗不会返还。");
    });
    if (roll.total >= 11) return false;
  });
  return;
}

if (pass !== "postActiveEffects" || !pending || workflow.slowFinished) return;
workflow.slowFinished = true;

await MidiQOL.completeActivityUse(pending.activity, {
  ...pending.usage, consume: false,
  midiOptions: {
    targetUuids: pending.targets, ignoreUserTargets: true,
    workflowOptions: { slowCompletion: true }
  }
}, { configure: false });
await fromUuidSync(pending.effect)?.delete();
